head.b:skin:
/* ==========================================================================
   SUNO MP3 & WAV DOWNLOADER - COMPLETE BLOGGER TEMPLATE (DARK STUDIO)
   ========================================================================== */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  background-color: #0a0a0a;
  color: #f5f5f5;
  font-family: 'Kantumruy Pro', 'Plus Jakarta Sans', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
  line-height: 1.6;
  selection-background-color: #f59e0b;
  selection-color: #0a0a0a;
}

::selection {
  background: #f59e0b;
  color: #0a0a0a;
}

a {
  color: #f59e0b;
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: #fbbf24;
}

/* Navigation Header */
.suno-navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  width: 100%;
  background: rgba(10, 10, 10, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(38, 38, 38, 0.8);
}

.suno-nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 14px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.suno-brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.suno-logo-icon {
  width: 38px;
  height: 38px;
  background: linear-gradient(135deg, #f59e0b, #d97706);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #000;
  font-weight: 900;
  font-size: 18px;
  box-shadow: 0 4px 12px rgba(245, 158, 11, 0.25);
}

.suno-brand-text {
  display: flex;
  flex-direction: column;
}

.suno-brand-title {
  font-size: 16px;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: -0.01em;
}

.suno-brand-sub {
  font-size: 11px;
  color: #a3a3a3;
}

.suno-nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.badge-quality {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(16, 185, 129, 0.1);
  border: 1px solid rgba(16, 185, 129, 0.25);
  color: #34d399;
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 9999px;
  font-family: 'JetBrains Mono', monospace;
}

.badge-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #10b981;
  animation: pulseDot 2s infinite ease-in-out;
}

@keyframes pulseDot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(0.8); }
}

.btn-fullscreen {
  background: #171717;
  border: 1px solid #262626;
  color: #d4d4d4;
  padding: 6px 14px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.2s;
}

.btn-fullscreen:hover {
  background: #262626;
  color: #ffffff;
}

/* Main Wrapper */
.suno-wrapper {
  flex: 1;
  max-width: 1200px;
  width: 100%;
  margin: 0 auto;
  padding: 32px 20px 48px;
}

/* Hero Title */
.suno-hero {
  text-align: center;
  margin-bottom: 28px;
}

.suno-hero-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(245, 158, 11, 0.1);
  border: 1px solid rgba(245, 158, 11, 0.25);
  color: #fbbf24;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 14px;
  border-radius: 9999px;
  margin-bottom: 14px;
}

.suno-hero-title {
  font-size: 32px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #ffffff;
  margin-bottom: 10px;
  line-height: 1.25;
}

@media (min-width: 768px) {
  .suno-hero-title {
    font-size: 42px;
  }
}

.suno-hero-desc {
  font-size: 15px;
  color: #a3a3a3;
  max-width: 700px;
  margin: 0 auto;
}

/* Tool Container */
.suno-tool-card {
  background: #121212;
  border: 1px solid #262626;
  border-radius: 18px;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.7), 0 0 25px rgba(245, 158, 11, 0.05);
  overflow: hidden;
  margin-bottom: 40px;
  position: relative;
}

.suno-tool-header {
  background: #171717;
  padding: 12px 20px;
  border-bottom: 1px solid #262626;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.suno-traffic-lights {
  display: flex;
  align-items: center;
  gap: 8px;
}

.traffic-dot {
  width: 11px;
  height: 11px;
  border-radius: 50%;
}

.traffic-red { background: #ef4444; }
.traffic-yellow { background: #f59e0b; }
.traffic-green { background: #10b981; }

.suno-frame-url {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  color: #737373;
  background: #0a0a0a;
  padding: 4px 14px;
  border-radius: 6px;
  border: 1px solid #262626;
}

.suno-frame-wrap {
  position: relative;
  width: 100%;
  min-height: 960px;
  background: #0a0a0a;
}

.suno-iframe {
  width: 100%;
  height: 960px;
  border: none;
  display: block;
}

/* Features Grid */
.suno-features {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 20px;
  margin-bottom: 48px;
}

.feature-card {
  background: #121212;
  border: 1px solid #262626;
  border-radius: 14px;
  padding: 24px;
  transition: transform 0.2s, border-color 0.2s;
}

.feature-card:hover {
  transform: translateY(-3px);
  border-color: #f59e0b;
}

.feature-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: rgba(245, 158, 11, 0.1);
  border: 1px solid rgba(245, 158, 11, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  margin-bottom: 16px;
}

.feature-title {
  font-size: 16px;
  font-weight: 700;
  color: #f5f5f5;
  margin-bottom: 8px;
}

.feature-desc {
  font-size: 13px;
  color: #a3a3a3;
  line-height: 1.5;
}

/* FAQ Accordion Section */
.suno-faq-section {
  background: #121212;
  border: 1px solid #262626;
  border-radius: 16px;
  padding: 32px 24px;
  margin-bottom: 48px;
}

.faq-heading {
  font-size: 22px;
  font-weight: 700;
  color: #ffffff;
  margin-bottom: 20px;
  text-align: center;
}

.faq-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 768px) {
  .faq-grid {
    grid-template-columns: 1fr 1fr;
  }
}

.faq-item {
  background: #171717;
  border: 1px solid #262626;
  border-radius: 12px;
  padding: 18px;
}

.faq-q {
  font-size: 14px;
  font-weight: 700;
  color: #fbbf24;
  margin-bottom: 8px;
}

.faq-a {
  font-size: 13px;
  color: #d4d4d4;
  line-height: 1.6;
}

/* Footer */
.suno-footer {
  background: #0d0d0d;
  border-top: 1px solid #262626;
  padding: 32px 20px;
  text-align: center;
  color: #737373;
  font-size: 13px;
  margin-top: auto;
}

.footer-sub {
  font-size: 12px;
  margin-top: 6px;
  color: #525252;
}

/* Blogger Required Hidden Section */
.blogger-content-section {
  display: none !important;
}

body.script:
//<![CDATA[
function toggleFullscreen() {
  var elem = document.getElementById('tool-container');
  if (!document.fullscreenElement) {
    if (elem.requestFullscreen) {
      elem.requestFullscreen();
    } else if (elem.webkitRequestFullscreen) {
      elem.webkitRequestFullscreen();
    } else if (elem.msRequestFullscreen) {
      elem.msRequestFullscreen();
    }
    document.getElementById('btn-toggle-fullscreen').innerText = '✕ ចេញពីពេញអេក្រង់';
  } else {
    if (document.exitFullscreen) {
      document.exitFullscreen();
    }
    document.getElementById('btn-toggle-fullscreen').innerText = '⛶ ពេញអេក្រង់';
  }
}

// Adjust iframe height dynamically if needed
window.addEventListener('message', function(event) {
  if (event.data && event.data.type === 'SUNO_RESIZE') {
    var iframe = document.getElementById('suno-app-iframe');
    if (iframe && event.data.height) {
      iframe.style.height = (event.data.height + 40) + 'px';
    }
  }
});
//]]>
